# 0.4.4: xp.wheat "24,46,66,85,103" -> idle XP per wheat for totem tier I..V (each 0..1000, 0.4.3's bounds); one number = every tier;
# missing = the default list; junk = the default list + one WARN; fewer than 5 = the last one repeats
F(cfg, "public static final int[] XPW_DEF = new int[] { %s };" % ", ".join(str(x) for x in XPW_LIST))
M(cfg, r"""
public static int[] xpwOf(String v) {
  int[] d = new int[5];
  for (int i = 0; i < 5; i++) d[i] = XPW_DEF[i];
  if (v == null || v.trim().length() == 0) return d;
  try {
    String[] a = v.trim().split(",");
    if (a.length < 1 || a.length > 5) throw new IllegalArgumentException("1 to 5 numbers");
    int last = 0;
    for (int i = 0; i < 5; i++) {
      if (i < a.length) {
        double x = Double.parseDouble(a[i].trim());
        if (Double.isNaN(x) || x < 0.0) x = 0.0;
        if (x > 1000.0) x = 1000.0;
        last = (int) Math.round(x);
      }
      d[i] = last;
    }
    return d;
  } catch (Throwable t) {
    warnOnce("xpw:" + v, "xp.wheat=" + v + " is not a list of numbers (like 24,46,66,85,103) - the default XP is used");
    for (int i = 0; i < 5; i++) d[i] = XPW_DEF[i];
    return d;
  }
}""")
M(cfg, r"""
public static double[] wmaxOf(String v) {
  double[] d = new double[5];
  for (int i = 0; i < 5; i++) d[i] = WMAX_DEF[i];
  if (v == null || v.trim().length() == 0) return d;
  try {
    String[] a = v.trim().split(",");
    if (a.length < 1 || a.length > 5) throw new IllegalArgumentException("1 to 5 numbers");
    double last = 0.0;
    for (int i = 0; i < 5; i++) {
      if (i < a.length) {
        double x = Double.parseDouble(a[i].trim());
        if (Double.isNaN(x) || x < 0.0) x = 0.0;
        if (x > 100000.0) x = 100000.0;
        last = x;
      }
      d[i] = last;
    }
    return d;
  } catch (Throwable t) {
    warnOnce("wmax:" + v, "totem.workerMax=" + v + " is not a list of numbers (like 12,24,48,96,192) - the default caps are used");
    for (int i = 0; i < 5; i++) d[i] = WMAX_DEF[i];
    return d;
  }
}""")
M(cfg, r"""
public static String num(long n) {
  String s = String.valueOf(n < 0L ? -n : n);
  StringBuilder sb = new StringBuilder();
  for (int i = 0; i < s.length(); i++) {
    if (i > 0 && (s.length() - i) % 3 == 0) sb.append(',');
    sb.append(s.charAt(i));
  }
  return (n < 0L ? "-" : "") + sb.toString();
}""")
M(cfg, r"""
public static String dec(double d) {
  long r = Math.round(d * 100.0);
  if (r % 100L == 0L) return String.valueOf(r / 100L);
  if (r % 10L == 0L) return (r / 100L) + "." + ((r % 100L) / 10L);
  return (r / 100L) + "." + ((r % 100L) < 10L ? "0" : "") + (r % 100L);
}""")
M(cfg, r"""
public static boolean writeDefaults() {
  try {
    if (FILE == null || java.nio.file.Files.exists(FILE, new java.nio.file.LinkOption[0])) return false;
    java.nio.file.Files.createDirectories(FILE.getParent(), new java.nio.file.attribute.FileAttribute[0]);
    java.nio.file.Files.write(FILE, DEFAULT_TEXT.getBytes("UTF-8"), new java.nio.file.OpenOption[] { java.nio.file.StandardOpenOption.CREATE_NEW, java.nio.file.StandardOpenOption.WRITE });
    return true;
  } catch (Throwable t) { warn("could not write the default config.properties: " + t); return false; }
}""")
