M(tot, r"""
public static double ownMult(String[] f, long t) {
  double m = 1.0 + 0.2 * (double) countMod(f, "faster") + 0.1 * (double) countMod(f, "replant") + 0.1 * (double) countMod(f, "compost");
  if (boosted(f, t)) m = m * (1.0 + (double) @PKG@.ShCfg.BOOST_PCT / 100.0);
  return m;
}""")
# a worker's items / minute on an island of `size`: min(tier speed x (crops in range / crops in the Harvest Spirit I range on a Small
# island), totem.workerMax) x its own modifiers / booster
M(tot, r"""
public static double workerRate(int kd, String[] f, int size, long t) {
  int ti = idx(f[0]);
  if (ti < 0 || !WORKER[ti] || !accepts(ti, kd)) return 0.0;   // 0.3: a worker works only in its own shards
  int ref = cov(1, @PKG@.ShCfg.RANGES[0]);
  if (ref < 1) ref = 1;
  double reach = (double) cov(size, range(f, t)) / (double) ref;
  double base = @PKG@.ShCfg.RATES[tierOf(f[1]) - 1] * reach;
  double[] wm = @PKG@.ShCfg.WMAXS;
  int tq = tierOf(f[1]) - 1;
  double mx = @PKG@.ShCfg.WORKER_MAX;
  if (wm != null && tq >= 0 && tq < wm.length) mx = wm[tq];   // 0.4.4: the cap of this totem's tier (totem.workerMax is a per-tier list)
  if (mx > 0.0 && base > mx) base = mx;   // fix4: spec 9.2 / 9.3 ceiling before the totem's own modifiers / booster
  return base * ownMult(f, t);
}""")
M(tot, "public static double workerRate(String[] f, int size, long t) { return workerRate(@PKG@.ShKind.FARM, f, size, t); }")
# a support totem's percent (day / night ones x the share; Harvest Moon = moon.bonus at night). 0.3: bonus / smelt totems add no percent
M(tot, r"""
public static double supportPct(int kd, String[] f, long t) {
  int ti = idx(f[0]);
  if (ti < 0 || WORKER[ti] || !accepts(ti, kd)) return 0.0;
  int e = EFFECT[ti];
  if (e == 5 || e == 6) return 0.0;
  double base = e == 4 ? (double) @PKG@.ShCfg.MOON_BONUS : (double) @PKG@.ShCfg.SUPPORT[tierOf(f[1]) - 1];
  double share = 1.0;
  if (e == 2) share = 1.0 - @PKG@.ShCfg.NIGHT;
  if (e == 3 || e == 4) share = @PKG@.ShCfg.NIGHT;
  return base * share * ownMult(f, t);
}""")
M(tot, "public static double supportPct(String[] f, long t) { return supportPct(@PKG@.ShKind.FARM, f, t); }")
