# the island's rate at time t (items / minute; no worker = 0); 0.3: x the shard's Time Compressor
M(tot, r"""
public static double islandRate(int kd, java.util.Properties p, int slot, int size, long t) {
  String[] e = entries(kd, p, slot);
  double w = 0.0;
  double s = 0.0;
  for (int i = 0; i < e.length; i++) {
    String[] f = parse(e[i]);
    w += workerRate(kd, f, size, t);
    s += supportPct(kd, f, t);
  }
  if (w <= 0.0) return 0.0;
  return w * (1.0 + s / 100.0) * tcMult(kd, p);
}""")
