# ms until the island's store is full at the rate of `now` (-1 = never / already full)
M(mth, r"""
public static long msToFull(int kd, java.util.Properties p, int slot, long now) {
  double r = rate(kd, p, slot, now);
  long left = capOf(kd, p, slot) - stored(kd, p, slot);
  if (r <= 0.0 || left <= 0L) return -1L;
  return (long) Math.ceil((double) left * 60000.0 / r);
}""")
M(mth, "public static long msToFull(java.util.Properties p, int slot, long now) { return msToFull(FK, p, slot, now); }")
# the first island of a new shard (spec 9.1: Wheat Small + one Harvest Spirit I; 0.3: each shard its own type + its starter worker I)
