M(mth, r"""
public static String fmtMs(long ms) {
  if (ms < 0L) return "-";
  long m = (ms + 59999L) / 60000L;
  if (m < 60L) return m + " m";
  long h = m / 60L;
  if (h < 48L) return h + " h " + (m % 60L) + " m";
  return (h / 24L) + " d " + (h % 24L) + " h";
}""")

# ================= ShGeo: the region layout (spec 9.1), pure maths - every block the region wants =================
# 0.3: one region per kind, 1,024 blocks apart on x (OX(kd) = 1024 x kd; Farming = 2048 as in 0.1 / 0.2); the island floor is the same
# for every kind (the totem maths count its tiles), the kind decides what stands on it (STYLE): crops, ore nodes, oak trees, apple trees,
# hay bales, an arena floor. Every gatherable block (crop, ore node, trunk, leaves, apple) is painted only where the block is AIR.
geo = mk("ShGeo")
F(geo, "public static final int OX = %d;" % REGION_X)      # 0.2's Farming origin (kept for the 0.2-signature methods)
F(geo, "public static final int OZ = %d;" % REGION_Z)
F(geo, "public static final int Y = %d;" % Y)
F(geo, "public static final int FK = %d;" % FARM_K)
F(geo, "public static final int[] SX = new int[] { %s };" % ", ".join(str(p[0]) for p in SLOT_POS))
F(geo, "public static final int[] SZ = new int[] { %s };" % ", ".join(str(p[1]) for p in SLOT_POS))
F(geo, "public static final int[] HALF = new int[] { %s };" % ", ".join(str(h) for h in HALF))
F(geo, "public static final int HUB = %d;" % HUB_HALF)
F(geo, "public static final int RING = %d;" % RING)
F(geo, "public static final int[] CX = new int[] { %s };" % ", ".join(str(c[0]) for c in CHUNKS))   # Farming's chunks; kind kd = + 32 x (kd - 2)
F(geo, "public static final int[] CZ = new int[] { %s };" % ", ".join(str(c[1]) for c in CHUNKS))
GEO_IDS = [BLOCKS[k] for k in ("grass", "dirt", "till", "stone", "brick", "plank", "crop", "stand")] + [""] + \
    [STYLE_BLOCKS[k] for k in ("ore", "oaktrunk", "oakleaf", "appletrunk", "appleleaf", "apple", "hay", "cobble", "mossy")] + SHARD_ITEMS
GEO_STANDS = [7 if _k == FARM_K else 18 + _k for _k in range(NK)]
assert GEO_IDS[7] == SHARD_ITEM and all(GEO_IDS[GEO_STANDS[_k]] == SHARD_ITEMS[_k] for _k in range(NK)) and len(GEO_IDS) == 24
F(geo, 'public static final String[] IDS = new String[] { %s };' % ", ".join([jlit(x) for x in GEO_IDS] + [jlit(x) for x in TOTEM_BLOCK] + [jlit(x) for x in BENCH_BLOCKS]))   # 0.4: + the benches
for _n, _k in enumerate(("GRASS", "DIRT", "TILL", "STONE", "BRICK", "PLANK", "CROP", "STAND", "AIR", "ORE", "OTRUNK", "OLEAF", "ATRUNK",
                         "ALEAF", "APPLE", "HAY", "COBBLE", "MOSSY")):
    F(geo, "public static final int %s = %d;" % (_k, _n))
F(geo, "public static final int[] STANDS = new int[] { %s };" % ", ".join(str(x) for x in GEO_STANDS))
F(geo, "public static final int TOTEM = %d;" % len(GEO_IDS))
F(geo, "public static final int BENCH = %d;" % (len(GEO_IDS) + NT))     # 0.4: IDS[BENCH + kind] = that shard's Totem Bench
F(geo, "public static final int BX = %d;" % BENCH_POS[0])
F(geo, "public static final int BZ = %d;" % BENCH_POS[1])
F(geo, 'public static final String[] STYLE = new String[] { %s };' % ", ".join(jlit(i["style"]) for i in ISL))
M(geo, "public static int ox(int kd) { return 1024 * kd; }")
M(geo, "public static int chunkX(int kd, int i) { return CX[i] + 32 * (kd - FK); }")
# a gatherable block: painted only where the block is AIR (a growing crop / a node someone stands next to is never reset)
M(geo, r"""
public static boolean res(int kind) {
  return kind == CROP || kind == ORE || kind == OTRUNK || kind == OLEAF || kind == ATRUNK || kind == ALEAF || kind == APPLE;
}""")
M(geo, r"""
public static void add(java.util.ArrayList out, int x, int y, int z, int kind) {
  out.add(new int[] { x, y, z, kind });
}""")
# a tree / bale grid point of an island (every 4 blocks from the centre, off the middle 5 x 5, 2 in from the rim)
M(geo, r"""
public static boolean grid(int dx, int dz, int h) {
  int ax = dx < 0 ? -dx : dx;
  int az = dz < 0 ? -dz : dz;
  if (ax > h - 2 || az > h - 2) return false;
  if (ax <= 2 && az <= 2) return false;
  return ((dx + 400) % 4) == 0 && ((dz + 400) % 4) == 0;
}""")
# the island of `size` around slot `slot` of kind kd (out: x, y, z, kind = index into IDS)
M(geo, r"""
public static void island(java.util.ArrayList out, int kd, int slot, int size) {
  int h = HALF[size < 1 ? 0 : (size > 3 ? 2 : size - 1)];
  int cx = ox(kd) + SX[slot];
  int cz = OZ + SZ[slot];
  String st = STYLE[kd];
  boolean farm = st.equals("farm");
  boolean mine = st.equals("mine");
  boolean arena = st.equals("arena");
  for (int dx = -h; dx <= h; dx++) for (int dz = -h; dz <= h; dz++) {
    int ax = dx < 0 ? -dx : dx;
    int az = dz < 0 ? -dz : dz;
    if (ax == h && az == h) continue;
    boolean rim = ax == h || az == h;
    boolean mid = ax <= 1 && az <= 1;
    int x = cx + dx; int z = cz + dz;
    if (rim) add(out, x, Y, z, mine ? COBBLE : (arena ? MOSSY : GRASS));
    else if (mid) add(out, x, Y, z, BRICK);
    else if (farm) { add(out, x, Y, z, TILL); add(out, x, Y + 1, z, CROP); }
    else if (mine) { add(out, x, Y, z, STONE); if (((dx + 400) % 2) == 0 && ((dz + 400) % 2) == 0 && !(ax <= 2 && az <= 2)) add(out, x, Y + 1, z, ORE); }
    else if (arena) add(out, x, Y, z, BRICK);
    else add(out, x, Y, z, GRASS);
    add(out, x, Y - 1, z, DIRT);
    if (ax <= h - 2 && az <= h - 2) add(out, x, Y - 2, z, STONE);
    if (ax <= h - 4 && az <= h - 4) add(out, x, Y - 3, z, STONE);
  }
  if (st.equals("grove") || st.equals("orchard") || st.equals("ranch")) {
    for (int dx = -h; dx <= h; dx++) for (int dz = -h; dz <= h; dz++) {
      if (!grid(dx, dz, h)) continue;
      int x = cx + dx; int z = cz + dz;
      if (st.equals("ranch")) { add(out, x, Y + 1, z, HAY); continue; }
      boolean oak = st.equals("grove");
      int top = oak ? Y + 3 : Y + 2;
      for (int y = Y + 1; y <= top; y++) add(out, x, y, z, oak ? OTRUNK : ATRUNK);
      for (int lx = -1; lx <= 1; lx++) for (int lz = -1; lz <= 1; lz++) add(out, x + lx, top + 1, z + lz, oak ? OLEAF : ALEAF);
      add(out, x, top + 2, z, oak ? OLEAF : ALEAF);
      if (oak) { add(out, x + 1, top, z, OLEAF); add(out, x - 1, top, z, OLEAF); add(out, x, top, z + 1, OLEAF); add(out, x, top, z - 1, OLEAF); }
      else { add(out, x + 1, top, z + 1, APPLE); add(out, x - 1, top, z - 1, APPLE); add(out, x + 1, top, z - 1, APPLE); add(out, x - 1, top, z + 1, APPLE); }
    }
  }
  add(out, cx, Y + 1, cz, BRICK);
  add(out, cx, Y + 2, cz, BRICK);
}""")
M(geo, "public static void island(java.util.ArrayList out, int slot, int size) { island(out, FK, slot, size); }")
M(geo, r"""
public static void hub(java.util.ArrayList out, int kd) {
  int h = HUB;
  int ox = ox(kd);
  for (int dx = -h; dx <= h; dx++) for (int dz = -h; dz <= h; dz++) {
    int ax = dx < 0 ? -dx : dx;
    int az = dz < 0 ? -dz : dz;
    if (ax + az > h + 3) continue;
    int x = ox + dx; int z = OZ + dz;
    add(out, x, Y, z, (ax <= 3 && az <= 3) ? BRICK : GRASS);
    add(out, x, Y - 1, z, DIRT);
    if (ax + az <= h) add(out, x, Y - 2, z, STONE);
    if (ax + az <= h - 3) add(out, x, Y - 3, z, STONE);
  }
  add(out, ox, Y + 1, OZ - 3, STANDS[kd]);
  add(out, ox + BX, Y + 1, OZ + BZ, BENCH + kd);   // 0.4 (spec 9.7): the shard's fixed Totem Bench - the repair (Enter / Grow) puts it back
}""")
