# ================= ShCore: the actions (world thread; every one re-checks its rules) =================
core = mk("ShCore")
F(core, 'public static final String ITEM = "%s";' % CROP["item"])
F(core, 'public static final String ENCH = "%s";' % CROP["ench"])
F(core, 'public static final String SEED = "%s";' % CROP["seed"])
F(core, 'public static final String COLL = "%s";' % CROP["coll"])
F(core, 'public static final String SHARD = "%s";' % SHARD_ITEM)
F(core, "public static final int FK = %d;" % FARM_K)
F(core, "public static volatile long NOW_TEST = 0L;")
F(core, "public static final java.util.concurrent.ConcurrentHashMap MEM_OWED = new java.util.concurrent.ConcurrentHashMap();")
# fix2: what waits in memory when the collector's file cannot be read (key "<pkey>|<owed key>") - taken once, never twice
M(core, r"""
public static long memTake(String ck, String key) {
  Object m = MEM_OWED.remove(ck + "|" + key);
  return m instanceof Long ? ((Long) m).longValue() : 0L;
}""")
M(core, r"""
public static void memKeep(String ck, String key, long left, java.util.UUID u) {
  if (left <= 0L) return;
  Object o = MEM_OWED.get(ck + "|" + key);
  long had = o instanceof Long ? ((Long) o).longValue() : 0L;
  MEM_OWED.put(ck + "|" + key, Long.valueOf(had + left));
  @PKG@.ShCfg.warnOnce("memowed:" + ck, "the collector file of " + ck + " could not be read - " + key + " " + left + " waits in memory until the next Collect (collect.log)");
  @PKG@.ShStore.log(u + " " + ck + " " + key + " " + left + " WAITS IN MEMORY (collector file unreadable)");
}""")
M(core, "public static long now() { long t = NOW_TEST; return t > 0L ? t : System.currentTimeMillis(); }")
# the collection credit for `add` new items of `item` + whatever waited from earlier refusals (owed.coll.<item> in the COLLECTOR's file)
M(core, r"""
public static long owed(java.util.UUID u, String item, long add) {
  String ck = @PKG@.ShCfg.pkey(u);
  java.util.Properties q = @PKG@.ShStore.get(ck);
  long due = add;
  String key = "owed.coll." + item;
  due += memTake(ck, key);   // fix2
  if (q != null) { @PKG@.ShStore.LOCK.lock(); try { due += @PKG@.ShStore.lng(q, key, 0L); } finally { @PKG@.ShStore.LOCK.unlock(); } }
  if (due <= 0L) return 0L;
  long done = @PKG@.ShPay.coll(u, item, due);
  long left = due - done;
  if (q == null) memKeep(ck, key, left, u);   // fix2: never dropped without a trace
  if (q != null) {
    @PKG@.ShStore.LOCK.lock(); try {
      long had = @PKG@.ShStore.lng(q, key, 0L);
      if (left != had) {
        if (left > 0L) q.setProperty(key, String.valueOf(left)); else q.remove(key);
        String e = @PKG@.ShStore.save(ck, q);
        if (e != null) @PKG@.ShCfg.warn("the waiting collection count could not be saved: " + e);
      }
    } finally { @PKG@.ShStore.LOCK.unlock(); }
  }
  return left;
}""")
M(core, "public static long owed(java.util.UUID u, long add) { return owed(u, ITEM, add); }")
# fix2: profile:busy:<uuid> = the live inventory may not belong to the active profile (tools/PROFILES-CONTRACT.md rule 5)
M(core, r"""
public static boolean busy(java.util.UUID u) {
  try { return u != null && Boolean.TRUE.equals(@PKG@.ShCfg.bridge().get("profile:busy:" + u)); } catch (Throwable t) { return false; }
}""")
# fix2: a placed record that went stale (the island was reset; its portal sits in the old backup world) pauses production the first time
# it is seen: settled up to now, then <kind>.paused = 1 (Pick up / placing again clears it as usual). The bridge is asked outside the lock.
M(core, r"""
public static boolean pauseStale(String k, int kd, java.util.Properties p) {
  if (k == null || p == null) return false;
  @PKG@.ShTotem.moonBlade(k);   // fix4: warm the Moon Blade cache outside ShStore.LOCK (settle reads only the cache)
  String placed;
  @PKG@.ShStore.LOCK.lock(); try {
    if (@PKG@.ShMath.paused(kd, p)) return false;
    placed = @PKG@.ShStore.str(p, @PKG@.ShMath.kk(kd, "placed"));
  } finally { @PKG@.ShStore.LOCK.unlock(); }
  if (placed.length() == 0 || !@PKG@.ShRole.stale(placed, k)) return false;
  @PKG@.ShStore.LOCK.lock(); try {
    if (@PKG@.ShMath.paused(kd, p) || !placed.equals(@PKG@.ShStore.str(p, @PKG@.ShMath.kk(kd, "placed")))) return false;
    java.util.Properties old = new java.util.Properties();
    old.putAll(p);
    @PKG@.ShMath.settleAll(kd, p, now());
    p.setProperty(@PKG@.ShMath.kk(kd, "paused"), "1");
    String e = @PKG@.ShStore.save(k, p);
    if (e != null) { p.clear(); p.putAll(old); @PKG@.ShCfg.warn("could not pause a reset island's shard: " + e); return false; }
  } finally { @PKG@.ShStore.LOCK.unlock(); }
  @PKG@.ShStore.log(k + " " + @PKG@.ShKind.KEYS[kd] + " placed record " + placed + " is stale (island reset) - production paused until the shard is placed again");
  return true;
}""")
M(core, "public static boolean pauseStale(String k, java.util.Properties p) { return pauseStale(k, FK, p); }")
# fix (critic): who may Collect / buy / Grow here (re-checked at every action, not only at Enter): null = yes, else the refusal line
M(core, r"""
public static String gate(java.util.UUID u, String k, int kd, java.util.Properties p) {
  if (busy(u)) return "-Your profile is still loading - try again in a moment.";   // fix2: PROFILES-CONTRACT rule 5
  pauseStale(k, kd, p);   // fix2: a portal left in a reset island makes nothing
  if (!@PKG@.ShRole.mayBeIn(u, k)) return "-Only the island owner and co-op members can use this shard.";
  if (!@PKG@.ShRole.mayManage(u, k)) return "-Only the island owner can collect and upgrade this shard.";
  boolean own;
  @PKG@.ShStore.LOCK.lock(); try { own = @PKG@.ShMath.owned(kd, p); } finally { @PKG@.ShStore.LOCK.unlock(); }
  if (!own) return "-No " + @PKG@.ShKind.NAMES[kd] + " Shard yet - it comes from the hub quest line.";
  return null;
}""")
M(core, "public static String gate(java.util.UUID u, String k, java.util.Properties p) { return gate(u, k, FK, p); }")
# 0.4.2 (Skyy 2026-10-16 "Co-op can Collect"): storage, the Auto-Compactor, the Time Compressor and Grow = the island OWNER only, whatever
# shard.coopCollect says (gate first: profile loading, co-op / visitor, owned)
M(core, r"""
public static String gateOwn(java.util.UUID u, String k, int kd, java.util.Properties p) {
  String no = gate(u, k, kd, p);
  if (no != null) return no;
  if (k == null || !k.equals(@PKG@.ShCfg.pkey(u))) return "-Only the island owner can buy upgrades and grow islands in this shard.";
  return null;
}""")
# fix (critic): skill XP for `add` items' worth + whatever waited (owed.xp = Farming, 0.2's key; owed.xp.<Skill> for the others, in the
# COLLECTOR's file); returns what still waits (-1 = nothing due)
M(core, r"""
public static long owedXp(java.util.UUID u, String skill, long add) {
  String ck = @PKG@.ShCfg.pkey(u);
  java.util.Properties q = @PKG@.ShStore.get(ck);
  long due = add;
  String key = "Farming".equals(skill) ? "owed.xp" : "owed.xp." + skill;
  due += memTake(ck, key);   // fix2
  if (q != null) { @PKG@.ShStore.LOCK.lock(); try { due += @PKG@.ShStore.lng(q, key, 0L); } finally { @PKG@.ShStore.LOCK.unlock(); } }
  if (due <= 0L) return -1L;
  long left = @PKG@.ShPay.xp(u, skill, due, "shard:" + skill.toLowerCase()) ? 0L : due;
  if (q == null) memKeep(ck, key, left, u);   // fix2: never dropped without a trace
  if (q != null) {
    @PKG@.ShStore.LOCK.lock(); try {
      long had = @PKG@.ShStore.lng(q, key, 0L);
      if (left != had) {
        if (left > 0L) q.setProperty(key, String.valueOf(left)); else q.remove(key);
        String e = @PKG@.ShStore.save(ck, q);
        if (e != null) @PKG@.ShCfg.warn("the waiting " + skill + " XP could not be saved: " + e);
      }
    } finally { @PKG@.ShStore.LOCK.unlock(); }
  }
  return left;
}""")
M(core, "public static long owedXp(java.util.UUID u, long add) { return owedXp(u, \"Farming\", add); }")
M(core, r"""
public static String lastKey(int kd) {
  return kd == FK ? "lastCollect" : @PKG@.ShMath.kk(kd, "lastCollect");
}""")
# Collect `slot` (-1 = every island) of shard kd for player u from profile k. Returns "+..." / "-..." (status line). The file is debited
# FIRST (written), then each island's items are given (counted): 0.3 - an island with an Auto-Smelt Pole gives the smelted item (ingots),
# an Auto-Compactor gives the Enchanted form of every full 100 (counted as 100 base items); the bonus finds (<kind>.i<n>.ench: Harvest Moon
# Enchanted Wheat / Tree Sap / Emerald / Linen) follow; what did not fit goes back to ITS island (written). Credits: the collection of the
# island's item (Ore_Copper also for ingots; x100 for compacted / Enchanted Wheat), the bonus find's own collection (Farming: as 100 Wheat),
# shard.xpPercent of the skill XP (Combat: none).
M(core, r"""
public static String collect0(java.util.UUID u, String k, int kd, int slot, @IC@[] cs) {   // 0.3.1: the 0.3 collect, renamed (the wrapper plays the sting)
  if (!@PKG@.ShCfg.ON) return "-Shards are switched off on this server.";
  if (cs == null) return "-Your inventory could not be read - try again.";
  java.util.Properties p = @PKG@.ShStore.get(k);
  if (p == null) return "-This shard's file could not be read - ask an admin to look at the server log.";
  String no = gate(u, k, kd, p);
  if (no != null) return no;
  String prod = @PKG@.ShKind.PROD[kd];
  String bon = @PKG@.ShKind.BONUS[kd];
  long want = 0L; long wantE = 0L;
  long baseGiven = 0L; long gItems = 0L; long gSmelt = 0L; long gEnch = 0L; long gBonus = 0L; long backM = 0L; long backB = 0L;
  double xpD = 0.0;   // 0.4.4: Farming XP before the percent (each island at its own totem tiers)
  @PKG@.ShStore.LOCK.lock(); try {
    long now = now();
    @PKG@.ShMath.settleAll(kd, p, now);
    int n = @PKG@.ShMath.SLOTS;
    long[] take = new long[n];
    long[] takeE = new long[n];
    double[] xa = new double[n];   // 0.4.4 fix 2
    for (int i = 0; i < n; i++) {
      if (slot >= 0 && i != slot) continue;
      take[i] = @PKG@.ShMath.stored(kd, p, i);
      takeE[i] = bon.length() == 0 ? 0L : @PKG@.ShMath.ench(kd, p, i);
      if (take[i] > 0L || takeE[i] > 0L) xa[i] = @PKG@.ShMath.xpAvg(kd, p, i, now);
      want += take[i];
      wantE += takeE[i];
    }
    if (want + wantE <= 0L) return "=Nothing is stored there yet.";
    java.util.Properties old = new java.util.Properties();
    old.putAll(p);
    for (int i = 0; i < n; i++) {
      if (take[i] > 0L) @PKG@.ShMath.xpSet(kd, p, i, @PKG@.ShMath.stored(kd, p, i) - take[i], (double) (@PKG@.ShMath.stored(kd, p, i) - take[i]) * xa[i]);   // 0.4.4 fix 2
      if (take[i] > 0L) p.setProperty(@PKG@.ShMath.ik(kd, i, "stored"), String.valueOf(@PKG@.ShMath.stored(kd, p, i) - take[i]));
      if (takeE[i] > 0L) p.setProperty(@PKG@.ShMath.ik(kd, i, "ench"), String.valueOf(@PKG@.ShMath.ench(kd, p, i) - takeE[i]));
    }
    p.setProperty(lastKey(kd), String.valueOf(now));   // fix2: the Collect tab's "Last collected ... ago"
    String err = @PKG@.ShStore.save(k, p);
    if (err != null) { p.clear(); p.putAll(old); @PKG@.ShCfg.warn("Collect refused (debit not written): " + err); return "-Collect failed: the shard file could not be saved. Nothing was taken."; }
    int cmp = @PKG@.ShMath.compactor(kd, p);
    long[] bm = new long[n];
    long[] bb = new long[n];
    for (int i = 0; i < n; i++) {
      double xi = xa[i];   // 0.4.4 fix 2: the XP of the tiers that MADE the items (ShMath.xpAvg, read before the debit)
      if (take[i] > 0L) {
        boolean sm = @PKG@.ShTotem.smelts(kd, p, i);
        String out = sm ? @PKG@.ShKind.SMELT[kd] : prod;
        String en = sm ? @PKG@.ShKind.SMELT_ENCH[kd] : @PKG@.ShKind.ENCH[kd];
        long e = (cmp >= 1 && en.length() > 0) ? take[i] / 100L : 0L;
        long ge = e > 0L ? @PKG@.ShInv.give(cs, en, e) : 0L;
        long rest = take[i] - 100L * e;
        long gr = rest > 0L ? @PKG@.ShInv.give(cs, out, rest) : 0L;
        long del = 100L * ge + gr;
        baseGiven += del;
        xpD += (double) del * xi;   // 0.4.4
        gEnch += ge;
        if (sm) gSmelt += gr; else gItems += gr;
        bm[i] = take[i] - del;
        backM += bm[i];
      }
      if (takeE[i] > 0L) {
        long gb = @PKG@.ShInv.give(cs, bon, takeE[i]);
        gBonus += gb;
        xpD += (double) gb * (@PKG@.ShKind.BMULT[kd] > 1 ? (double) @PKG@.ShKind.BMULT[kd] * xi : (double) @PKG@.ShKind.BXP[kd]);   // 0.4.4
        bb[i] = takeE[i] - gb;
        backB += bb[i];
      }
    }
    if (backM > 0L || backB > 0L) {
      for (int i = 0; i < n; i++) {
        if (bm[i] > 0L) @PKG@.ShMath.xpSet(kd, p, i, @PKG@.ShMath.stored(kd, p, i) + bm[i], (double) (@PKG@.ShMath.stored(kd, p, i) + bm[i]) * xa[i]);   // 0.4.4 fix 2
        if (bm[i] > 0L) p.setProperty(@PKG@.ShMath.ik(kd, i, "stored"), String.valueOf(@PKG@.ShMath.stored(kd, p, i) + bm[i]));
        if (bb[i] > 0L) p.setProperty(@PKG@.ShMath.ik(kd, i, "ench"), String.valueOf(@PKG@.ShMath.ench(kd, p, i) + bb[i]));
      }
      String e2 = @PKG@.ShStore.save(k, p);
      if (e2 != null) @PKG@.ShCfg.warn("Collect: " + backM + " + " + backB + " items that did not fit are back in memory but not on disk yet: " + e2);
    }
    @PKG@.ShStore.log(u + " " + k + (kd == FK ? "" : " " + @PKG@.ShKind.KEYS[kd]) + " slot " + slot + " debit " + want + " given " + baseGiven + " back " + backM + (wantE > 0L ? " ench debit " + wantE + " given " + gBonus + " back " + backB : "") + (gEnch > 0L ? " compacted " + gEnch : "") + (gSmelt > 0L ? " smelted " + gSmelt : ""));
  } finally { @PKG@.ShStore.LOCK.unlock(); }
  String extra = "";
  int bm1 = @PKG@.ShKind.BMULT[kd];
  long collMain = baseGiven + (bm1 > 1 ? (long) bm1 * gBonus : 0L);   // the alias rule: an Enchanted crop counts as 100 of its base item
  if (baseGiven + gBonus > 0L) {
    String skill = @PKG@.ShKind.SKILL[kd];
    long per = (long) @PKG@.ShCfg.xpOf(kd);
    long bxp = bm1 > 1 ? (long) bm1 * per : (long) @PKG@.ShKind.BXP[kd];
    boolean fx = kd == FK;   // 0.4.4: Farming pays each island's totem-tier XP (xp.wheat per tier)
    if (per > 0L || bxp > 0L || (fx && xpD > 0.0)) {   // Combat: drops only (Skyy G9), no XP call at all
      long xp = fx ? (long) Math.floor(xpD * (double) @PKG@.ShCfg.XP_PCT / 100.0 + 0.000000001) : (baseGiven * per + gBonus * bxp) * (long) @PKG@.ShCfg.XP_PCT / 100L;
      long xpLeft = owedXp(u, skill, xp);   // fix (critic): unpaid XP waits in the collector's file and is paid on a later Collect
      if (xpLeft > 0L) extra = extra + " (" + @PKG@.ShCfg.num(xpLeft) + " " + skill + " XP waits - paid on your next Collect)";
      else if (xp > 0L) extra = extra + " +" + @PKG@.ShCfg.num(xp) + " " + skill + " XP";
    }
    long owedC = collMain > 0L ? owed(u, prod, collMain) : 0L;
    if (owedC > 0L) extra = extra + " - " + @PKG@.ShCfg.num(owedC) + " " + @PKG@.ShTotem.pretty(prod) + " collection count waiting";
    if (bm1 <= 1 && gBonus > 0L) {
      long owedB = owed(u, bon, gBonus);
      if (owedB > 0L) extra = extra + " - " + @PKG@.ShCfg.num(owedB) + " " + @PKG@.ShTotem.pretty(bon) + " collection count waiting";
    }
  }
  if (baseGiven + gBonus <= 0L) return "-Your inventory is full - nothing was collected.";
  StringBuilder got = new StringBuilder();
  if (gItems > 0L || (gSmelt == 0L && gEnch == 0L)) got.append(@PKG@.ShCfg.num(gItems)).append(' ').append(@PKG@.ShTotem.pretty(prod));
  if (gSmelt > 0L) { if (got.length() > 0) got.append(" + "); got.append(@PKG@.ShCfg.num(gSmelt)).append(' ').append(@PKG@.ShTotem.pretty(@PKG@.ShKind.SMELT[kd])); }
  if (gEnch > 0L) { if (got.length() > 0) got.append(" + "); got.append(@PKG@.ShCfg.num(gEnch)).append(" Enchanted (compacted)"); }
  if (gBonus > 0L) got.append(" + ").append(@PKG@.ShCfg.num(gBonus)).append(' ').append(@PKG@.ShTotem.pretty(bon)).append(kd == FK ? " (Harvest Moon)" : " (rare finds)");
  long left = backM + backB;
  return "+Collected " + got.toString() + extra + (left > 0L ? ". " + @PKG@.ShCfg.num(left) + " did not fit and stay in the shard." : ".");
}""")
