# grow an island one size (coins, the shard's grow item, its collection tier); pasted at once if the shard world is loaded
M(core, r"""
public static String grow0(java.util.UUID u, String k, int kd, int slot, @IC@[] cs) {   // 0.3.1: the 0.3 grow, renamed (the wrapper plays the sting)
  if (!@PKG@.ShCfg.ON) return "-Shards are switched off on this server.";
  java.util.Properties p = @PKG@.ShStore.get(k);
  if (p == null) return "-This shard's file could not be read.";
  if (cs == null) return "-Your inventory could not be read - try again.";
  String no = gateOwn(u, k, kd, p);   // 0.4.2: the owner only
  if (no != null) return no;
  if (slot < 0 || slot >= @PKG@.ShMath.SLOTS) return "-Pick an island first.";
  Object[] gi = @PKG@.ShCfg.growOf(kd);
  if (gi == null) return "-The grow cost setting of this shard is broken - ask an admin (Server Setup -> Shards).";
  String item = (String) gi[0];
  String what = kd == FK ? "seeds" : @PKG@.ShTotem.pretty(item);
  String res;
  @PKG@.ShStore.LOCK.lock(); try {
    if (!@PKG@.ShMath.hasIsland(kd, p, slot)) return "-That slot has no island yet.";
    int sz = @PKG@.ShMath.size(kd, p, slot);
    if (sz >= 3) return "=That island is fully grown.";
    long coins = sz == 1 ? (long) @PKG@.ShCfg.GM_COINS : (long) @PKG@.ShCfg.GL_COINS;
    long seeds = ((Long) (sz == 1 ? gi[1] : gi[2])).longValue();
    int need = sz == 1 ? @PKG@.ShCfg.GM_COLL : @PKG@.ShCfg.GL_COLL;
    int tier = @PKG@.ShPay.collTier(u, @PKG@.ShKind.COLL[kd]);
    if (need > 0 && tier < need) return "-Needs " + @PKG@.ShKind.CNAME[kd] + " collection " + need + " (you: " + (tier < 0 ? "?" : String.valueOf(tier)) + ").";
    long have = @PKG@.ShInv.count(cs, item);
    if (have < seeds) return "-You need " + seeds + " " + @PKG@.ShTotem.pretty(item) + " (you have " + have + ").";
    long purse = @PKG@.ShPay.coins(u);
    if (coins > 0L && purse >= 0L && purse < coins) return "-You need " + @PKG@.ShCfg.num(coins) + " coins (you have " + @PKG@.ShCfg.num(purse) + ").";
    @PKG@.ShMath.settle(kd, p, slot, now());
    long got = @PKG@.ShInv.take(cs, item, seeds);
    if (got < seeds) { @PKG@.ShInv.give(cs, item, got); return "-The " + what + " could not be taken - nothing was bought."; }
    if (!@PKG@.ShPay.takeCoins(u, coins)) { long r = @PKG@.ShInv.give(cs, item, got); @PKG@.ShStore.log(u + " " + k + " grow refund " + r + " of " + got + " " + item); return "-The coins could not be taken - your " + what + " are back."; }
    java.util.Properties old = new java.util.Properties();
    old.putAll(p);
    p.setProperty(@PKG@.ShMath.ik(kd, slot, "size"), String.valueOf(sz + 1));
    String e = @PKG@.ShStore.save(k, p);
    if (e != null) {   // fix (critic): not saved = undone + everything paid goes back
      p.clear(); p.putAll(old);
      long ri = @PKG@.ShInv.give(cs, item, got);
      boolean rc = @PKG@.ShPay.addCoins(u, coins);
      @PKG@.ShStore.log(u + " " + k + " grow slot " + slot + " SAVE FAILED " + e + " - refund " + ri + " of " + got + " " + item + ", coins " + (rc ? coins : 0L) + " of " + coins);
      @PKG@.ShCfg.warn("grow not saved, refunded: " + e);
      return "-The island could not be saved - your " + what + (rc ? " and coins are" : " are") + " back." + (rc ? "" : " Ask an admin about the " + @PKG@.ShCfg.num(coins) + " coins (collect.log).");
    }
    @PKG@.ShStore.log(u + " " + k + (kd == FK ? "" : " " + @PKG@.ShKind.KEYS[kd]) + " grow slot " + slot + " " + sz + " -> " + (sz + 1) + " paid " + coins + " coins + " + got + " " + item);
    res = "+The " + @PKG@.ShKind.TNAME[kd] + " island grew to " + (sz == 1 ? "Medium" : "Large") + ".";
  } finally { @PKG@.ShStore.LOCK.unlock(); }
  @PKG@.ShWorld2.repaint(k, kd);
  return res;
}""")
