# fix (critic shards03): a shard handed out by an admin (or later a quest) counts as one the profile HAD - <kind>.crafted = 1 is saved
# BEFORE the item exists (like craft), so stashing it unplaced cannot open a second craft at rebirth 2. Inventory full = the mark is
# taken back only when this call set it. null = given, else the refusal line.
M(adm, r"""
public static String giveShard(String k, int kd, @IC@[] cs) {
  if (cs == null) return "-Their inventory could not be read.";
  java.util.Properties p = @PKG@.ShStore.get(k);
  if (p == null) return "-Their shard file could not be read.";
  boolean had;
  @PKG@.ShStore.LOCK.lock(); try { had = "1".equals(@PKG@.ShStore.str(p, @PKG@.ShMath.kk(kd, "crafted"))); } finally { @PKG@.ShStore.LOCK.unlock(); }
  if (!had && !@PKG@.ShCore.markCrafted(k, kd, true)) return "-Their shard file could not be saved - nothing given.";
  if (@PKG@.ShInv.give(cs, @PKG@.ShKind.SHARD[kd], 1L) >= 1L) return null;
  if (!had) @PKG@.ShCore.markCrafted(k, kd, false);
  return "-Their inventory is full.";
}""")
M(adm, r"""
public static java.util.ArrayList run(String args) {
  java.util.ArrayList out = new java.util.ArrayList();
  String[] a = args == null || args.trim().length() == 0 ? new String[0] : args.trim().split("\\s+");
  if (a.length < 2) { out.add("-" + USAGE); return out; }
  String cmd = a[0].toLowerCase();
  if (!cmd.equals("give") && !cmd.equals("info") && !cmd.equals("unplace") && !cmd.equals("unload") && !cmd.equals("totem")) { out.add("-Unknown: " + cmd + ". " + USAGE); return out; }
  @PR@ t = player(a[1]);
  if (t == null || !t.isValid()) { out.add("-That player is not online."); return out; }
  String k = @PKG@.ShCfg.pkey(t.getUuid());
  if (cmd.equals("give")) {
    int kd = kindArg(a, 2);
    if (kd < 0) { out.add("-Unknown shard " + a[2] + ". Shards: " + @PKG@.ShKind.keysList() + "."); return out; }
    @REF@ r = t.getReference();
    if (r == null || !r.isValid()) { out.add("-That player is not in a world."); return out; }
    String gg = giveGate(t.getUuid(), t.getUsername(), r);   // fix3 + fix4
    if (gg != null) { out.add(gg); return out; }
    String ge = giveShard(k, kd, @PKG@.ShInv.containers(r.getStore(), r));   // fix (critic shards03): marks <kind>.crafted first
    long got = ge == null ? 1L : 0L;
    String nm = @PKG@.ShKind.NAMES[kd];
    if (got > 0L) @PKG@.ShStore.log("admin give " + t.getUsername() + " " + @PKG@.ShKind.SHARD[kd]);
    out.add(got > 0L ? "+Gave a " + nm + " Shard to " + t.getUsername() + "." : ge);
    if (got > 0L) @PKG@.ShSay.to(t, "[Shards] You got a " + nm + " Shard. Place it on your island, then right-click it.", "#39f493");
    return out;
  }
  if (cmd.equals("totem")) {   // 0.2: any totem at any tier (testing the tiers before SkyyGear's Anvil exists)
    if (a.length < 3) { out.add("-Usage: /shardadmin totem <player> <type> [tier 1-5]. Types: " + String.join(", ", @PKG@.ShTotem.KEYS)); return out; }
    int ti = @PKG@.ShTotem.idx(a[2].toLowerCase());
    if (ti < 0) { out.add("-Unknown totem type " + a[2] + ". Types: " + String.join(", ", @PKG@.ShTotem.KEYS)); return out; }
    int tier = a.length > 3 ? @PKG@.ShTotem.tierOf(a[3]) : 1;
    @REF@ r = t.getReference();
    if (r == null || !r.isValid()) { out.add("-That player is not in a world."); return out; }
    String gg = giveGate(t.getUuid(), t.getUsername(), r);   // fix3 + fix4
    if (gg != null) { out.add(gg); return out; }
    String[] f = new String[] { @PKG@.ShTotem.KEYS[ti], String.valueOf(tier), "", "", "0", @PKG@.ShTotem.newUid() };
    boolean ok = @PKG@.ShInv.giveStack(@PKG@.ShInv.containers(r.getStore(), r), @PKG@.ShTotem.stack(f, @PKG@.ShCore.now()));
    if (ok) @PKG@.ShCore.tlog("admin give " + t.getUsername() + " " + @PKG@.ShTotem.fmt(f));
    out.add(ok ? "+Gave " + @PKG@.ShTotem.name(f) + " to " + t.getUsername() + "." : "-Their inventory is full.");
    return out;
  }
  java.util.Properties p = @PKG@.ShStore.get(k);
  if (cmd.equals("info")) {
    if (p == null) { out.add("-The shard file of " + t.getUsername() + " could not be read."); return out; }
    @PKG@.ShTotem.moonBlade(k);   // fix4: outside the lock
    @PKG@.ShStore.LOCK.lock(); try {
      long now = @PKG@.ShCore.now();
      out.add("=" + t.getUsername() + " (" + k + "): world " + @PKG@.ShWorlds.name(k) + (@PKG@.ShWorlds.loaded().contains(@PKG@.ShWorlds.name(k)) ? " (loaded)" : " (unloaded)"));
      for (int kd = 0; kd < @PKG@.ShKind.N; kd++) {   // 0.3: every shard the profile has
        String pl = @PKG@.ShStore.str(p, @PKG@.ShMath.kk(kd, "placed"));
        if (!@PKG@.ShMath.owned(kd, p) && pl.length() == 0) continue;
        @PKG@.ShMath.settleAll(kd, p, now);
        out.add("=" + @PKG@.ShKind.NAMES[kd] + ": placed " + (pl.length() == 0 ? "no" : pl) + ", storage tier " + @PKG@.ShMath.storageTier(kd, p) + ", compactor " + @PKG@.ShMath.compactor(kd, p) + ", compressor " + @PKG@.ShMath.compressor(kd, p) + (@PKG@.ShMath.paused(kd, p) ? ", PAUSED" : ""));
        for (int i = 0; i < @PKG@.ShMath.SLOTS; i++) if (@PKG@.ShMath.hasIsland(kd, p, i)) out.add("=  slot " + (i + 1) + ": " + @PKG@.ShStore.str(p, @PKG@.ShMath.ik(kd, i, "type")) + " size " + @PKG@.ShMath.size(kd, p, i) + ", stored " + @PKG@.ShMath.stored(kd, p, i) + " / " + @PKG@.ShMath.capOf(kd, p, i) + " (+" + @PKG@.ShMath.ench(kd, p, i) + " bonus), " + @PKG@.ShCfg.dec(@PKG@.ShMath.rate(kd, p, i, now)) + " / min, totems " + @PKG@.ShStore.str(p, @PKG@.ShMath.ik(kd, i, "totems")));
      }
    } finally { @PKG@.ShStore.LOCK.unlock(); }
    return out;
  }
  if (cmd.equals("unplace")) {
    int kd = kindArg(a, 2);
    if (kd < 0) { out.add("-Unknown shard " + a[2] + ". Shards: " + @PKG@.ShKind.keysList() + "."); return out; }
    if (p == null) { out.add("-The shard file of " + t.getUsername() + " could not be read."); return out; }
    String was;
    @PKG@.ShStore.LOCK.lock(); try {
      was = @PKG@.ShStore.str(p, @PKG@.ShMath.kk(kd, "placed"));
      @PKG@.ShMath.settleAll(kd, p, @PKG@.ShCore.now());
      p.remove(@PKG@.ShMath.kk(kd, "placed"));
      if (@PKG@.ShMath.owned(kd, p)) p.setProperty(@PKG@.ShMath.kk(kd, "paused"), "1");
      String e = @PKG@.ShStore.save(k, p);
      if (e != null) { out.add("-Could not save: " + e); return out; }
    } finally { @PKG@.ShStore.LOCK.unlock(); }
    @PKG@.ShStore.log("admin unplace " + k + " " + @PKG@.ShKind.KEYS[kd] + " was " + was);
    out.add("+" + t.getUsername() + "'s " + @PKG@.ShKind.NAMES[kd] + " Shard record is cleared (was: " + (was.length() == 0 ? "not placed" : was.replace('|', ' ')) + "). Its islands are kept; give a new shard item with /shardadmin give " + t.getUsername() + " " + @PKG@.ShKind.KEYS[kd] + " if the old block is gone.");
    return out;
  }
  String n = @PKG@.ShWorlds.name(k);   // unload
  @WLD@ w = @UNI@.get().getWorld(n);
  if (w == null) { out.add("=" + n + " is not loaded."); return out; }
  if (w.getPlayerCount() > 0) { out.add("-Someone is inside " + n + " - it unloads once it is empty."); return out; }
  out.add(@UNI@.get().removeWorld(n) ? "+Unloaded " + n + " (the folder stays)." : "-Could not unload " + n + ".");
  return out;
}""")
