# ================= shard:fn:give (fix2, critic shards03 2nd round): the quest bridge for "all T1 shards come from quests" =================
# Object[]{ java.util.UUID player, String shard key (mining / foraging / farming / ranching / orchard / combat) } -> String, called on that
# player's WORLD THREAD (a quest reward). "+..." = given (<kind>.crafted = 1 saved BEFORE the item, ShAdmin.giveShard); "=..." = the
# profile already HAD that shard (placed once / crafted / given - hasShard) so nothing is given (the quest may count it as done);
# "-..." = refused, nothing given (unknown shard, not online, another thread, profile switching, inventory full, file not saved).
# Unlike /shardadmin give (an admin replacing a lost shard) it never hands out a second shard of a kind.
gfn = mk("ShGiveFn", None, ("java.util.function.Function",))
F(gfn, "public static volatile java.util.function.Function PLAYER_TEST = null;")   # harness: UUID -> PlayerRef stand-in
C(gfn, "public ShGiveFn() { }")
M(gfn, r"""
public static String give(java.util.UUID u, String key, @PR@ t) {
  if (!@PKG@.ShCfg.ON) return "-Shards are switched off on this server.";
  int kd = key == null ? -1 : @PKG@.ShKind.ofKey(key.toLowerCase());
  if (kd < 0) return "-Unknown shard " + key + ". Shards: " + @PKG@.ShKind.keysList() + ".";
  if (@PKG@.ShCore.busy(u)) return "-The profile is switching - try again in a moment.";
  String k = @PKG@.ShCfg.pkey(u);
  if (@PKG@.ShCore.hasShard(k, kd)) return "=" + @PKG@.ShCore.haveShard(kd);
  if (t == null || !t.isValid()) return "-That player is not online.";
  @REF@ r = t.getReference();
  if (r == null || !r.isValid()) return "-That player is not in a world.";
  String gg = @PKG@.ShAdmin.giveGate(u, t.getUsername(), r);
  if (gg != null) return gg;
  String ge = @PKG@.ShAdmin.giveShard(k, kd, @PKG@.ShInv.containers(r.getStore(), r));
  if (ge != null) return ge;
  @PKG@.ShStore.log("bridge give " + t.getUsername() + " " + @PKG@.ShKind.SHARD[kd]);
  return "+You got your " + @PKG@.ShKind.NAMES[kd] + " Shard. Place it on your island, then right-click it.";
}""")
M(gfn, r"""
public Object apply(Object o) {
  try {
    if (!(o instanceof Object[])) return "-Bad call: Object[]{ UUID, String shard }.";
    Object[] a = (Object[]) o;
    if (a.length < 2 || !(a[0] instanceof java.util.UUID) || !(a[1] instanceof String)) return "-Bad call: Object[]{ UUID, String shard }.";
    java.util.UUID u = (java.util.UUID) a[0];
    @PR@ t;
    if (PLAYER_TEST != null) { Object x = PLAYER_TEST.apply(u); t = x instanceof @PR@ ? (@PR@) x : null; }
    else t = @UNI@.get().getPlayer(u);
    return give(u, (String) a[1], t);
  } catch (Throwable t) { @PKG@.ShCfg.warn("shard:fn:give failed: " + t); return "-The shard could not be given (server log)."; }
}""")

